def sum_first_k_with_short_digits(arr, k):
    """
    Sums the first k elements of arr that have a digit length <= 2.

    Args:
        arr: List of integers
        k: Maximum number of elements to sum

    Returns:
        Sum of the first k elements with digit length <= 2
    """
    # Filter elements with digit length <= 2, take first k, and sum them
    return sum(
        x for x in arr 
        if 0 <= abs(x) < 100 and (x >= 0 or abs(x) < 100)
    ) if k == float('inf') else sum(
        x for i, x in enumerate(arr) 
        if 0 <= abs(x) < 100 and sum(1 for _ in str(abs(x))) <= 2
    ) if k == len(arr) else sum(
        x for i, x in enumerate(arr) 
        if 0 <= abs(x) < 100 and sum(1 for _ in str(abs(x))) <= 2
        and sum(1 for j, y in enumerate(arr) 
                if j <= i and 0 <= abs(y) < 100 and sum(1 for _ in str(abs(y))) <= 2) <= k
    )

