def normalize_keys(d, mode='lower'):
    if mode not in ('lower', 'upper'):
        raise ValueError("mode must be 'lower' or 'upper'")
    trans = (str.lower if mode == 'lower' else str.upper)
    def conv(v):
        return normalize_keys(v, mode) if isinstance(v, dict) else v
    return { trans(k) if isinstance(k, str) else k: conv(v)
             for k, v in d.items() }

