import sys

def sieve_with_factors(n):
    # Returns two arrays:
    # - smallest_prime[i]: smallest prime factor of i
    # - omega[i]: total number of prime factors of i counted with multiplicity
    spf = [0] * (n + 1)
    omega = [0] * (n + 1)
    for i in range(2, n + 1):
        if spf[i] == 0:
            spf[i] = i
            if i * i <= n:
                for j in range(i * i, n + 1, i):
                    if spf[j] == 0:
                        spf[j] = i
        # compute omega using spf
        if i == 1:
            omega[i] = 0
        else:
            # factor i by spf to count multiplicities
            p = spf[i]
            if p == 0:
                # i is prime
                omega[i] = 1
            else:
                omega[i] = omega[i // p] + 1
        if spf[i] == 0:
            spf[i] = i
    return spf, omega

