    """
    Returns a tuple (max_negative, min_positive) where:
    - max_negative is the largest negative number in nums (closest to zero) or None if no negative numbers.
    - min_positive is the smallest positive number in nums or None if no positive numbers.
    If the smallest/largest respectively are missing, return None for that position.
    """
    max_negative = None
    min_positive = None

    for x in nums:
        if x < 0:
            if (max_negative is None) or (x > max_negative):
                max_negative = x
        elif x > 0:
            if (min_positive is None) or (x < min_positive):
                min_positive = x
        # zeros are ignored per spec (not negative or positive)

