from typing import List

def is_prime(n: int) -> bool:
    """Check if a number is prime."""
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    return all(n % i != 0 for i in range(3, int(n**0.5) + 1, 2))

def sum_digits(n: int) -> int:
    """Calculate the sum of digits of a number."""
    return reduce(lambda acc, d: acc + int(d), str(abs(n)), 0)

def process_list(numbers: List[int]) -> int:
    """Sorts the list descending, finds the first prime number, 
    and returns the sum of its digits."""
    return next(
        (sum_digits(n) for n in sorted(numbers, reverse=True) if is_prime(n)),
        0
    )

